@If (ChkDate= ""; @Return(@Do(@Command([EditGotoField];"ChkDate") ;@Prompt([Ok];"Missing Value"; "Please enter Checked By Date before proceeding!")));"");

@Command([FileSave]);

FIELD CA				:="Submitted";
FIELD ReminderDate := @Today;

@Command([FileSave]);

@MailSend(HR;Approver:DocAuthor;NULL; @DbTitle + " : Pending your Action.";NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

